   153→    /// 사용자 프로세스 생성
   154→    pub fn create_user_process(
   155→        &mut self,
   156→        entry_point: u64,
   157→        stack_start: u64,
   158→        stack_size: u64,
   159→    ) -> Result<UserContext, &'static str> {
   160→        if stack_start == 0 || stack_size == 0 {
   161→            return Err("Invalid stack parameters");
   162→        }
   163→
   164→        let stack_top = stack_start + stack_size - 1;
   165→        let context = UserContext::new(entry_point, stack_top);
   166→
   167→        self.active_user_processes += 1;
   168→        crate::println!("👤 User process created (entry: 0x{:x}, stack: 0x{:x}-0x{:x})",
   169→            entry_point, stack_start, stack_top);
   170→
   171→        Ok(context)
   172→    }
