   173→                        self.advance();
   174→                        Token::Comma
   175→                    }
   176→                    '.' => {
   177→                        self.advance();
   178→                        Token::Dot
   179→                    }
   180→                    ':' => {
   181→                        self.advance();
   182→                        Token::Colon
   183→                    }
   184→                    ';' => {
   185→                        self.advance();
   186→                        Token::Semicolon
   187→                    }
   188→                    '|' => {
   189→                        self.advance();
   190→                        Token::Pipe
   191→                    }
   192→                    '+' => {
   193→                        self.advance();
