                self.call_builtin(name, args)
            }

            Expr::ArrayAppend { array, item } => {
                match self.eval_expr(array) {
                    Value::Array(mut arr) => {
                        arr.push(self.eval_expr(item));
                        Value::Array(arr)
                    }
                    _ => Value::Null,
                }
            }

            Expr::StructConstruct { name, fields } => {
                let mut struct_val = HashMap::new();
                for (k, v) in fields {
                    struct_val.insert(k.clone(), self.eval_expr(v));
                }
                Value::Struct(struct_val)
            }
        }
    }

    // Apply binary operators
    fn apply_binop(&self, left: &Value, op: &str, right: &Value) -> Value {
        match (left, right) {
            (Value::Integer(l), Value::Integer(r)) => {
                let result = match op {
                    "+" => l + r,
                    "-" => l - r,
                    "*" => l * r,
                    "/" => if *r != 0 { l / r } else { 0 },
                    "%" => if *r != 0 { l % r } else { 0 },
                    "==" => return Value::Boolean(l == r),
                    "!=" => return Value::Boolean(l != r),
                    "<" => return Value::Boolean(l < r),
                    ">" => return Value::Boolean(l > r),
                    "<=" => return Value::Boolean(l <= r),
                    ">=" => return Value::Boolean(l >= r),
                    _ => 0,
                };
                Value::Integer(result)
            }

            (Value::String(l), Value::String(r)) if op == "+" => {
                Value::String(format!("{}{}", l, r))
            }

            _ => Value::Null,
        }
    }

    // Built-in functions
    fn call_builtin(&self, name: &str, args: &[Expr]) -> Value {
        match name {
            "println" => {
                for arg in args {
                    println!("{}", self.eval_expr(arg).to_string());
                }
                Value::Null
            }

            "length" => {
                if let Some(arg) = args.first() {
                    match self.eval_expr(arg) {
                        Value::Array(arr) => Value::Integer(arr.len() as i64),
                        Value::String(s) => Value::Integer(s.len() as i64),
                        _ => Value::Integer(0),
                    }
                } else {
                    Value::Integer(0)
                }
            }

            "range" => {
                // Returns an array [start, start+1, ..., end-1]
                if args.len() >= 2 {
                    let start = match self.eval_expr(&args[0]) {
                        Value::Integer(n) => n,
                        _ => 0,
                    };
                    let end = match self.eval_expr(&args[1]) {
                        Value::Integer(n) => n,
                        _ => 0,
                    };

                    let mut result = Vec::new();
                    for i in start..end {
                        result.push(Value::Integer(i));
                    }
                    Value::Array(result)
                } else {
                    Value::Array(vec![])
                }
            }

            "str" => {
                if let Some(arg) = args.first() {
                    Value::String(self.eval_expr(arg).to_string())
                } else {
                    Value::String(String::new())
                }
            }

            _ => Value::Null,
        }
    }

    // Execute statement
    pub fn exec_stmt(&mut self, stmt: &Stmt) {
        match stmt {
            Stmt::VarDecl { name, value } => {
                let val = self.eval_expr(value);
                self.env.set(name.clone(), val);
            }

            Stmt::Assign { name, value } => {
                let val = self.eval_expr(value);
                self.env.set(name.clone(), val);
            }

            Stmt::ForLoop { var, start, end, body } => {
                for i in *start..*end {
                    self.env.set(var.clone(), Value::Integer(i));
                    for stmt in body {
                        self.exec_stmt(stmt);
                    }
                }
            }

            Stmt::If { condition, then_body, else_body } => {
                let cond_val = self.eval_expr(condition);
                if cond_val.is_truthy() {
                    for stmt in then_body {
                        self.exec_stmt(stmt);
                    }
                } else if let Some(els) = else_body {
                    for stmt in els {
                        self.exec_stmt(stmt);
                    }
                }
            }

            Stmt::Return(Some(expr)) => {
                self.return_value = Some(self.eval_expr(expr));
            }

            Stmt::Return(None) => {
                self.return_value = Some(Value::Null);
            }

            Stmt::Expr(expr) => {
                let _ = self.eval_expr(expr);
            }
        }
    }
}

